/**
 * The shipped icons must be derived from the real brand mark.
 *
 * The icon family drifted once: `public/favicon-*.png`, `public/favicon.ico` and
 * `public/brand/icon-*.png` were a hand-drawn navy tile generated by nobody in
 * particular, while the actual artwork sat unused at
 * `public/brand/logo-mark-raw.png`. Nothing connected the two, so the tab icon,
 * the installed-app icon and the logo in the header were three different things
 * and no check failed.
 *
 * `scripts/generate-brand-icons.mjs --check` re-derives every icon into memory
 * and compares bytes. That is the whole guard: it cannot rot because it does not
 * store its own expectation.
 *
 * The two rules that are easy to break by hand and are asserted here because the
 * generator had both bugs at once:
 *
 *  - every icon must be EXACTLY the size its filename promises. The source mark
 *    is 381x395, so a centred pad lands on an odd remainder and rounding both
 *    sides the same way emitted a 49x48 "48x48" icon.
 *  - every icon must contain real ink. A smooth resample of strokes ~15px wide
 *    in a 381px source produces, at 16px, an image with zero opaque pixels --
 *    which still looks like a written file.
 */
import { execFileSync } from "node:child_process";
import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { describe, it, expect } from "vitest";
import sharp from "sharp";

const ROOT = process.cwd();
const MARK = join(ROOT, "public/brand/logo-mark-raw.png");

const ICONS: Array<[string, number]> = [
  ["public/favicon-16.png", 16],
  ["public/favicon-32.png", 32],
  ["public/favicon-48.png", 48],
  ["public/favicon-96.png", 96],
  ["public/apple-icon.png", 180],
  ["public/brand/icon-192.png", 192],
  ["public/brand/icon-512.png", 512],
  // The mark on transparent at near-zero padding, for compositing onto
  // arbitrary backgrounds. It used to be drawn by a separate generator, so it was
  // the one brand asset that did not come from the real artwork.
  ["public/brand/logo-mark.png", 192],
  // Next's file-convention icon. It takes precedence over the `icons` array in
  // app/layout.tsx, and it shipped the navy tile for the entire time the
  // public/ favicons were being regenerated correctly — so this is the file that
  // actually decides what a browser tab shows.
  ["app/icon.png", 512],
];

describe("brand icons are derived from the real mark", () => {
  it("has the source artwork the icons are generated from", () => {
    // Without this every other rule below is vacuous.
    expect(existsSync(MARK), "public/brand/logo-mark-raw.png is the icon source").toBe(true);
  });

  it("reports no drift between the source mark and the shipped icons", () => {
    // The real assertion, in the generator's own words. A failure here names the
    // stale files in its stderr.
    const out = execFileSync("node", ["scripts/generate-brand-icons.mjs", "--check"], {
      cwd: ROOT,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    });
    expect(out).toContain("all icons match the source mark");
  });

  for (const [file, size] of ICONS) {
    it(`${file} is exactly ${size}x${size} and has visible ink`, async () => {
      const { data, info } = await sharp(join(ROOT, file))
        .ensureAlpha()
        .raw()
        .toBuffer({ resolveWithObject: true });

      expect(`${info.width}x${info.height}`).toBe(`${size}x${size}`);

      let opaque = 0;
      for (let i = 3; i < data.length; i += 4) if (data[i] >= 250) opaque++;
      // A mark drawn as strokes covers a few percent of its box; anything under
      // this has been resampled into a wash.
      expect(opaque / (size * size), `${file} opaque coverage`).toBeGreaterThan(0.04);
    });
  }

  it("no longer carries the retired green #119446", async () => {
    // scripts/recolor-brand-assets.mjs rebased the header logo onto #008338 and
    // deliberately left logo-mark-raw.png out of its file list, so the mark still
    // shipped the retired colour. The generator recolours it; this catches a
    // revert that drops that step.
    for (const [file] of ICONS) {
      const { data } = await sharp(join(ROOT, file)).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
      for (let i = 0; i < data.length; i += 4) {
        if (data[i + 3] < 250) continue;
        const hex = `#${[data[i], data[i + 1], data[i + 2]]
          .map((v) => v.toString(16).padStart(2, "0"))
          .join("")}`;
        expect(hex.toLowerCase(), `${file} carries the retired green`).not.toBe("#119446");
      }
    }
  });

  it("favicon.ico is a real ICO container carrying 16/32/48", () => {
    const ico = readFileSync(join(ROOT, "public/favicon.ico"));
    expect(ico.readUInt16LE(0)).toBe(0); // reserved
    expect(ico.readUInt16LE(2)).toBe(1); // 1 = icon
    expect(ico.readUInt16LE(4)).toBe(3); // three sizes packed

    for (let i = 0; i < 3; i++) {
      const at = 6 + i * 16;
      const bytes = ico.readUInt32LE(at + 8);
      const offset = ico.readUInt32LE(at + 12);
      expect(offset + bytes, `entry ${i} stays inside the file`).toBeLessThanOrEqual(ico.length);
      // PNG payload signature -- browsers accept PNG-compressed ICO entries.
      expect([...ico.subarray(offset, offset + 4)]).toEqual([0x89, 0x50, 0x4e, 0x47]);
    }
  });

  it("every icon the root layout references actually exists", async () => {
    // app/layout.tsx listed `/apple-icon.png`, which was never written. It
    // resolved to a 404 on every page and nothing reported it, because a
    // metadata URL is not a module import and the build does not check it.
    const layout = readFileSync(join(ROOT, "app/layout.tsx"), "utf8");
    const referenced = [...layout.matchAll(/url:\s*"(\/[^"]+\.(?:png|ico|svg))"/g)].map((m) => m[1]);
    expect(referenced.length, "the layout really does declare icons").toBeGreaterThan(0);
    for (const url of new Set(referenced)) {
      expect(existsSync(join(ROOT, "public", url.replace(/^\//, ""))), `${url} is referenced by app/layout.tsx`).toBe(true);
    }
  });

  it("the vector icons no longer put a navy tile behind the mark", () => {
    // The tile was the whole reason the vector and the raster looked like two
    // different brands.
    for (const file of ["public/brand/icon-32.svg", "public/brand/icon-192.svg"]) {
      const svg = readFileSync(join(ROOT, file), "utf8");
      expect(svg, `${file} must not paint a background rect`).not.toMatch(/<rect[^>]*fill/i);
      expect(svg, `${file} keeps the current palette`).toMatch(/#008338/i);
    }
  });

  it("app/favicon.ico is a real ICO container too", () => {
    // `tests/seo-payslip.test.ts` asserts this file exists. It used to exist only
    // because a THIRD generator happened to write it, so the assertion was
    // really asserting "some script ran at some point". Now the assertion and
    // the source agree.
    expect(existsSync(join(ROOT, "app/favicon.ico")), "app/favicon.ico exists").toBe(true);
    const ico = readFileSync(join(ROOT, "app/favicon.ico"));
    expect(ico.readUInt16LE(0)).toBe(0); // reserved
    expect(ico.readUInt16LE(2)).toBe(1); // 1 = icon
    expect(ico.readUInt16LE(4)).toBe(3); // three sizes packed
  });
});

/**
 * The Google Organization logo is the asset Google's Knowledge Panel shows.
 *
 * It is a different SHAPE from the favicon -- the mark on an opaque white plate
 * -- so it needs different assertions. A dimension check alone would pass on a
 * blank white square, and a coverage check would pass on anything, because on a
 * white plate every pixel is opaque. What can actually go wrong is that the
 * plate is empty, or that the artwork on it is the wrong colour.
 *
 * The colour rule is stated on the PIXELS rather than on the file's provenance,
 * because the provenance is what went wrong before: the logo was produced by a
 * generator that drew the mark as an SVG path in the retired green, and the
 * colour was corrected afterwards by a different script. The order was the bug.
 */
describe("the Google Organization logo is the real mark on a white plate", () => {
  const PLATES: Array<[string, number]> = [
    ["public/brand/google-organization-logo.png", 512],
    ["public/brand/google-organization-logo-112.png", 112],
  ];

  for (const [file, size] of PLATES) {
    it(`${file} is ${size}x${size}, opaque, and carries the mark`, async () => {
      const { data, info } = await sharp(join(ROOT, file))
        .raw()
        .toBuffer({ resolveWithObject: true });

      expect(`${info.width}x${info.height}`).toBe(`${size}x${size}`);

      let ink = 0;
      let greenDominant = 0;
      let retired = 0;
      for (let i = 0; i < data.length; i += 3) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        // The plate is white and the mark is green, so "ink" is anything
        // meaningfully darker than white.
        if (Math.min(r, g, b) < 250) {
          ink++;
          if (g > r && g > b) greenDominant++;
        }
        if (r === 0x11 && g === 0x94 && b === 0x46) retired++;
      }

      expect(ink / (size * size), `${file} has visible artwork`).toBeGreaterThan(0.01);
      // A blend of the brand green with white is still green-dominant; a grey
      // smudge is not. This is what separates "the logo" from "something was
      // drawn here".
      expect(greenDominant / ink, `${file} artwork is the green mark`).toBeGreaterThan(0.9);
      // EXACT equality, not a tolerance radius: the recolour moves each pixel
      // only PART way to the new hue, so a radius-based test fires on perfectly
      // good antialiased edges and would have to be silenced. An exact hit is an
      // interior pixel the recolour never reached.
      expect(retired, `${file} carries no retired-green pixel`).toBe(0);
    });
  }
});

/**
 * The social share card is generated from the brand assets, not painted once.
 *
 * The shipped card had a green pill with "BEEPA" typed into it instead of the
 * logo, the tagline baked in as "Partnership" while `BRAND.tagline` says
 * "Process", and it was 1200x630 while `app/layout.tsx` declared 1672x941 —
 * which is the number social platforms actually lay the card out from.
 */
describe("the OG share card matches the brand assets", () => {
  it("is not stale", () => {
    const out = execFileSync("node", ["scripts/generate-og-image.mjs", "--check"], {
      cwd: ROOT,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    });
    expect(out).toContain("og image matches the brand assets");
  });

  it("declares the same size to social platforms as it actually is", async () => {
    const { width, height } = await sharp(join(ROOT, "public/images/og.png")).metadata();

    // Comments stripped: the metadata carries a note explaining this exact bug,
    // and an unstripped search would match the prose instead of the numbers.
    const layout = readFileSync(join(ROOT, "app/layout.tsx"), "utf8")
      .replace(/\/\*[\s\S]*?\*\//g, "")
      .split(/\r?\n/)
      .map((line) => {
        const i = line.indexOf("//");
        return i === -1 || line.slice(0, i).includes(":") ? line : line.slice(0, i);
      })
      .join("\n");

    const declared = /url:\s*BRAND\.ogImageUrl,[\s\S]{0,120}?width:\s*(\d+),[\s\S]{0,60}?height:\s*(\d+)/
      .exec(layout);
    expect(declared, "app/layout.tsx declares an OG size at all").not.toBeNull();
    expect(Number(declared![1])).toBe(width);
    expect(Number(declared![2])).toBe(height);
  });

  it("is the standard share-card ratio a 1.905 crop expects", async () => {
    const { width, height } = await sharp(join(ROOT, "public/images/og.png")).metadata();
    expect(width / height).toBeCloseTo(1200 / 630, 2);
  });
});